static void write_le_dispatch_hit_telemetry(uint32_t turn,int frontier,int mcb_valid) {
    FILE *out=fopen("evidence/native_le_dispatch_hit_telemetry.json","wb");
    if(!out) return;
    fprintf(out,"{\n  \"schema\": \"gw-native-le-dispatch-hit-telemetry/v1\",\n"
                "  \"turn\": %u,\n  \"frontier\": %s,\n  \"MCB_chain_valid\": %s,\n"
                "  \"distinct_pairs\": %u,\n  \"pairs\": [\n",
        turn,frontier?"true":"false",mcb_valid?"true":"false",
        gw_recomp_dispatch_hits_count());
    const uint32_t count=gw_recomp_dispatch_hits_count();
    for(uint32_t i=0;i<count;i++) {
        uint32_t site=0u,target=0u; uint64_t hits=0u;
        if(!gw_recomp_dispatch_hits_get(i,&site,&target,&hits)) continue;
        fprintf(out,"    {\"callsite_eip\": \"0x%08X\", \"target_va\": \"0x%08X\", \"hit_count\": %llu}%s\n",
            site,target,(unsigned long long)hits,i+1u<count?",":"");
    }
    fputs("  ]\n}\n",out); fclose(out);
}

