#define GW_MAP_CENSUS_CAP 4096u
typedef struct gw_map_census_row {
    uint32_t ptr,first_tick,last_tick,calls,projected_count;
    int32_t screen_x,screen_y;
    uint8_t thing_type,field_2d,field_45,field_46,field_4c;
    uint8_t candidate_logged,ttype5_logged,projection_logged;
    int16_t world_x,world_y;
    const char *array_name;
    uint32_t array_index;
} gw_map_census_row;
static gw_map_census_row g_map_census[GW_MAP_CENSUS_CAP];
static uint32_t g_map_census_count;
static int g_drop_zone_entity_sweep;
static uint32_t g_drop_zone_target_ptr;
static int32_t g_drop_zone_target_x=INT32_MIN,g_drop_zone_target_y=INT32_MIN;
static uint8_t g_drop_zone_entity_scan_done;
static gw_map_census_row *gw_map_census_lookup(uint32_t p) {
    for(uint32_t i=0;i<g_map_census_count;i++)
        if(g_map_census[i].ptr==p) return &g_map_census[i];
    return NULL;
}
static gw_map_census_row *gw_map_census_find(uint32_t p) {
    gw_map_census_row *r=NULL;
    for(uint32_t i=0;i<g_map_census_count;i++) if(g_map_census[i].ptr==p) { r=&g_map_census[i]; break; }
    if(!r) {
        if(g_map_census_count>=GW_MAP_CENSUS_CAP) return NULL;
        r=&g_map_census[g_map_census_count++];
        memset(r,0,sizeof(*r)); r->ptr=p; r->first_tick=g_map_pick_trace_tick;
        r->last_tick=g_map_pick_trace_tick; r->screen_x=r->screen_y=INT32_MIN;
        r->array_name="not-in-known-BioGame-array";
        /* These extents and strides are from exact 1.1 MAP/InitArray_* evidence. */
        struct range { uint32_t start,end,stride; const char *name; };
        static const struct range ranges[]={
            {0x0032CF86u,0x003350D6u,0x7Cu,"BioGame::__creatures"},
            {0x003360D6u,0x0033C2D6u,0x31u,"BioGame::__plants"},
            {0x0033C2D6u,0x0033D276u,0xC8u,"BioGame::__team"},
            {0x0033D276u,0x00341576u,0x43u,"BioGame::__buildings"},
            {0x00341576u,0x003454BEu,0x51u,"BioGame::__effects"},
            {0x003454BEu,0x00345ADEu,0x31u,"BioGame::__events"},
            {0x00345ADEu,0x003466FEu,0x61u,"BioGame::__drones"},
            {0x003466FEu,0x00346CFEu,0x66u,"BioGame::__unkarr01"}
        };
        for(unsigned i=0;i<sizeof(ranges)/sizeof(ranges[0]);i++) if(p>=ranges[i].start&&p<ranges[i].end) {
            uint32_t off=p-ranges[i].start; r->array_name=ranges[i].name;
            r->array_index=off/ranges[i].stride;
            if(off%ranges[i].stride) r->array_name="array-interior-pointer";
            break;
        }
    }
    /* Refresh the sample at each encounter; state fields can evolve over ticks. */
    if(guest_memory && p<=0x03002000u-0x80u) {
        r->thing_type=guest_memory[p+6u]; r->field_2d=guest_memory[p+0x2Du];
        r->field_45=guest_memory[p+0x45u]; r->field_46=guest_memory[p+0x46u];
        r->field_4c=guest_memory[p+0x4Cu];
        r->world_x=(int16_t)(guest_memory[p+7u]|((uint16_t)guest_memory[p+8u]<<8));
        r->world_y=(int16_t)(guest_memory[p+9u]|((uint16_t)guest_memory[p+10u]<<8));
    }
    return r;
}
/* At the original game-loop boundary after Turn 300's Draw, census only
   live building/effect records already projected by the original map code.
   A target is queued only when its Thing+0x2d tag is 5 and the current Draw
   supplied an in-viewport projection. No guest data is changed. */
static void gw_drop_zone_scan_entities(uint32_t turn) {
    if(!guest_memory || g_drop_zone_entity_scan_done || turn!=300u) return;
    g_drop_zone_entity_scan_done=1u;
    static const struct { uint32_t start,count,stride; const char *name; } arrays[]={
        {0x0033D276u,256u,0x43u,"BioGame::__buildings"},
        {0x00341576u,200u,0x51u,"BioGame::__effects"}
    };
    unsigned active[2]={0,0},tag5[2]={0,0},projected_tag5[2]={0,0};
    fprintf(stderr,"TRACE drop_zone_entity_scan_begin Turn=%u arrays=buildings:256x67,effects:200x81 criterion=ttype_nonzero_and_byte_2d_5_target_requires_projection_this_draw\n",turn);
    for(unsigned a=0;a<2u;a++) for(uint32_t i=0;i<arrays[a].count;i++) {
        uint32_t p=arrays[a].start+i*arrays[a].stride;
        uint8_t type=guest_memory[p+6u],tag=guest_memory[p+0x2Du];
        if(type) active[a]++;
        if(!type || tag!=5u) continue;
        tag5[a]++;
        gw_map_census_row *row=gw_map_census_lookup(p);
        int projected=row && row->projected_count && row->last_tick==turn &&
            row->screen_x>=0 && row->screen_x<640 && row->screen_y>=0 && row->screen_y<480;
        if(projected) projected_tag5[a]++;
        int16_t wx=(int16_t)(guest_memory[p+7u]|((uint16_t)guest_memory[p+8u]<<8));
        int16_t wy=(int16_t)(guest_memory[p+9u]|((uint16_t)guest_memory[p+10u]<<8));
        fprintf(stderr,"TRACE drop_zone_entity_match Turn=%u array=%s index=%u ptr=%08x ttype=%02x byte2d=%02x field45=%02x field46=%02x field4c=%02x owner18=%u world=%d,%d projected_this_draw=%u screen=%d,%d calls=%u\n",
            turn,arrays[a].name,i,p,type,tag,guest_memory[p+0x45u],guest_memory[p+0x46u],
            guest_memory[p+0x4Cu],guest_memory[p+0x18u],wx,wy,projected,
            row?row->screen_x:INT32_MIN,row?row->screen_y:INT32_MIN,row?row->calls:0u);
        if(projected && !g_drop_zone_target_ptr) {
            g_drop_zone_target_ptr=p; g_drop_zone_target_x=row->screen_x; g_drop_zone_target_y=row->screen_y;
        }
    }
    fprintf(stderr,"TRACE drop_zone_entity_scan_end Turn=%u buildings_active=%u buildings_tag5=%u buildings_projected_tag5=%u effects_active=%u effects_tag5=%u effects_projected_tag5=%u chosen=%08x screen=%d,%d\n",
        turn,active[0],tag5[0],projected_tag5[0],active[1],tag5[1],projected_tag5[1],
        g_drop_zone_target_ptr,g_drop_zone_target_x,g_drop_zone_target_y);
}
