/* ---- creature_aim helpers (read-only; used only to place SDL events) ---- */
typedef struct { int x0,y0,x1,y1; } gw_aim_rect;
static uint32_t gw_aim_u32(uint32_t a) {
    return (guest_memory && a<0x03002000u-4u)?*(uint32_t *)(guest_memory+a):0u;
}
static int gw_aim_s16(uint32_t a) {
    return (guest_memory && a<0x03002000u-2u)?(int)*(int16_t *)(guest_memory+a):0;
}
static unsigned gw_aim_u8(uint32_t a) {
    return (guest_memory && a<0x03002000u)?guest_memory[a]:0u;
}
/* Geometry of the original creature hit-test, replicated read-only from
   0x46BC0 -> 0x69E50 (frame record) -> 0x90450 (sub-sprite walk) -> 0x903F0
   (bounding-rectangle test).  Output rectangles are absolute logical 640x480
   screen coordinates, half-open [x0,x1) x [y0,y1).  The anchor is
   (X + MapDisplay+0x1D, Y - ((Thing+0x27 - Thing+0x11) >> 6)); X and the
   already height-corrected Y come from the 0x78BA4 hook. */
static unsigned gw_creature_hit_rects(gw_aim_rect *out,unsigned max_out,int *scale_out) {
    const uint32_t c=0x0032CF86u, map=0x00346D70u;
    if(!guest_memory || !g_creature_aim_valid) return 0u;
    int sc=(int)((gw_aim_u8(c+0x76u)*gw_aim_u8(c+0x77u))/100u);
    if(sc>=0x100) sc=0x100;
    if(sc<=0x96) sc=0x96;
    if(scale_out) *scale_out=sc;
    const uint32_t entry=gw_aim_u32(c+0x1Fu)+gw_aim_u8(c+0x19u)*10u;
    const unsigned count=gw_aim_u8(entry+8u);
    unsigned frame=gw_aim_u8(c+0x1Bu);
    if(frame>=count) frame=(count-1u)&0xFFu;
    const uint32_t rec=gw_aim_u32(entry)+frame*14u;
    const uint32_t arr=gw_aim_u32(rec);
    const unsigned n=gw_aim_u8(rec+0xBu);
    const int sx=g_creature_aim_x+gw_aim_s16(map+0x1Du);
    const int sy=g_creature_aim_y;
    unsigned k,m=0u;
    for(k=0u;k<n && m<max_out;k++) {
        const uint32_t r=arr+k*10u;
        const uint32_t hp=gw_aim_u32(r);
        if(!hp) continue;
        const int ox=(gw_aim_s16(r+4u)*sc)/256;  /* trunc toward zero, as 0x9047F..0x9048C */
        const int oy=(gw_aim_s16(r+6u)*sc)/256;
        const int w=(int)((gw_aim_u8(hp+4u)*(unsigned)sc)>>8);
        const int h=(int)((gw_aim_u8(hp+5u)*(unsigned)sc)>>8);
        if(w<=0 || h<=0) continue;
        out[m].x0=sx+ox; out[m].y0=sy+oy; out[m].x1=sx+ox+w; out[m].y1=sy+oy+h;
        m++;
    }
    return m;
}
/* Pick the attempt-th point inside the largest rectangle: centre first, then
   four quarter points.  Returns 0 if no valid logical point exists. */
static int gw_creature_aim_point(unsigned attempt,int *lx,int *ly) {
    gw_aim_rect r[16]; int sc=0; unsigned i,best=0u,n=gw_creature_hit_rects(r,16u,&sc);
    long best_area=-1;
    for(i=0u;i<n;i++) {
        const long a=(long)(r[i].x1-r[i].x0)*(long)(r[i].y1-r[i].y0);
        if(a>best_area) { best_area=a; best=i; }
    }
    if(!n) return 0;
    static const int fx[5]={2,1,3,2,2}, fy[5]={2,2,2,1,3};
    const unsigned a=attempt%5u;
    int px=r[best].x0+(r[best].x1-r[best].x0)*fx[a]/4;
    int py=r[best].y0+(r[best].y1-r[best].y0)*fy[a]/4;
    if(px<r[best].x0) { px=r[best].x0; }
    if(px>=r[best].x1) { px=r[best].x1-1; }
    if(py<r[best].y0) { py=r[best].y0; }
    if(py>=r[best].y1) { py=r[best].y1-1; }
    if(px<128 || px>=640 || py<0 || py>=480) return 0;
    *lx=px; *ly=py; return 1;
}
