/* One-shot read-only census of the canonical Thing arrays at the native
   frame edge.  The scan observes Thing+0x1c and +0x17; it never changes guest
   state and does not run in the instruction hot path outside the turn test. */
static void gw_test_census_thing_1c_turn435(void) {
    if(!guest_memory || g_thing_1c_census_done ||
       *(uint32_t *)(guest_memory+0x002F1472u)!=435u) return;
    g_thing_1c_census_done=1u;
    static const struct { uint32_t start,count,stride; const char *name; } arrays[]={
        {0x0032CF86u,300u,0x7Cu,"BioGame::__creatures"},
        {0x003360D6u,512u,0x31u,"BioGame::__plants"},
        {0x0033C2D6u,20u,0xC8u,"BioGame::__team/PlSpec slots"},
        {0x0033D276u,256u,0x43u,"BioGame::__buildings"},
        {0x00341576u,200u,0x51u,"BioGame::__effects"}
    };
    fprintf(stderr,"TRACE thing_1c_census_begin turn=435 arrays=creatures:300x124,plants:512x49,team:20x200,buildings:256x67,effects:200x81 predicate=(byte+1c&1)!=0 && byte+17!=0 mapdisplay_guest=00346d70 mapdisplay_1c=%02x mapdisplay_1f=%04x\n",
        guest_memory[0x00346D8Cu],*(uint16_t *)(guest_memory+0x00346D8Fu));
    for(unsigned a=0;a<sizeof(arrays)/sizeof(arrays[0]);a++) {
        const uint64_t end=(uint64_t)arrays[a].start+(uint64_t)arrays[a].count*arrays[a].stride;
        if(end>0x03002000u) {
            fprintf(stderr,"TRACE thing_1c_census_range_invalid array=%s start=%08x count=%u stride=%u end=%llx\n",
                arrays[a].name,arrays[a].start,arrays[a].count,arrays[a].stride,(unsigned long long)end);
            continue;
        }
        for(uint32_t i=0;i<arrays[a].count;i++) {
            const uint32_t p=arrays[a].start+i*arrays[a].stride;
            const uint8_t type=guest_memory[p+6u],field17=guest_memory[p+0x17u];
            const uint8_t field1c=guest_memory[p+0x1Cu];
            if(type) g_thing_1c_census_active[a]++;
            if((field1c&1u)==0u || field17==0u) continue;
            g_thing_1c_census_matches[a]++;
            const int16_t wx=(int16_t)(guest_memory[p+7u]|((uint16_t)guest_memory[p+8u]<<8));
            const int16_t wy=(int16_t)(guest_memory[p+9u]|((uint16_t)guest_memory[p+10u]<<8));
            fprintf(stderr,"TRACE thing_1c_match turn=435 array=%s index=%u ptr=%08x type06=%02x subtype07=%02x owner18=%02x byte17=%02x byte1c=%02x byte2d=%02x world=%d,%d\n",
                arrays[a].name,i,p,type,guest_memory[p+7u],guest_memory[p+0x18u],field17,field1c,
                guest_memory[p+0x2Du],wx,wy);
        }
        g_thing_1c_census_total[a]=arrays[a].count;
        fprintf(stderr,"TRACE thing_1c_array_summary turn=435 array=%s slots=%u active_type06_nonzero=%u predicate_matches=%u\n",
            arrays[a].name,arrays[a].count,g_thing_1c_census_active[a],g_thing_1c_census_matches[a]);
    }
    fprintf(stderr,"TRACE thing_1c_census_end turn=435 mapdisplay_1c=%02x mapdisplay_1f=%04x selectedThing=%08x thing=%08x selectedPlSpec=%08x\n",
        guest_memory[0x00346D8Cu],*(uint16_t *)(guest_memory+0x00346D8Fu),
        *(uint32_t *)(guest_memory+0x00346DA7u),*(uint32_t *)(guest_memory+0x00346D88u),
        *(uint32_t *)(guest_memory+0x002F1434u));
}
