static SDL_Keycode gw_v28_key(const char *n) {
    if(!strcmp(n,"f10")) return SDLK_F10; if(!strcmp(n,"space")) return SDLK_SPACE; if(!strcmp(n,"return")) return SDLK_RETURN;
    if(!strcmp(n,"esc")) return SDLK_ESCAPE; if(!strcmp(n,"bksp")) return SDLK_BACKSPACE;
    if(!strcmp(n,"tab")) return SDLK_TAB; if(!strcmp(n,"up")) return SDLK_UP; if(!strcmp(n,"down")) return SDLK_DOWN;
    if(!strcmp(n,"left")) return SDLK_LEFT; if(!strcmp(n,"right")) return SDLK_RIGHT;
    if(n[0]>='0' && n[0]<='9' && !n[1]) return (SDL_Keycode)n[0];
    if(n[0]>='a' && n[0]<='z' && !n[1]) return (SDL_Keycode)n[0];
    return 0;
}
static void gw_v28_load(const char *path) {
    FILE *f=fopen(path,"r"); char line[160]; g_v28_n=g_v28_next=0;
    while(f && fgets(line,sizeof line,f) && g_v28_n<512u) {
        gw_v28_ev e; memset(&e,0,sizeof e); unsigned it=0;
        if(line[0]=='#' || sscanf(line,"%u %15s",&it,e.cmd)<2) continue;
        const char *p=strstr(line,e.cmd)+strlen(e.cmd);
        if(!strcmp(e.cmd,"key")) sscanf(p,"%15s %15s",e.a,e.b);
        else if(!strcmp(e.cmd,"move")) sscanf(p,"%d %d",&e.x,&e.y);
        else if(!strcmp(e.cmd,"mdown")||!strcmp(e.cmd,"mup")) sscanf(p,"%15s %d %d",e.a,&e.x,&e.y);
        else if(!strcmp(e.cmd,"shot")) sscanf(p,"%15s",e.a);
        else if(!strcmp(e.cmd,"scan")) { int x0=0,y0=0,x1=0,y1=0,st=8; sscanf(p,"%d %d %d %d %d",&x0,&y0,&x1,&y1,&st); e.x=x0; e.y=y0; snprintf(e.a,sizeof e.a,"%d",x1-x0); snprintf(e.b,sizeof e.b,"%d,%d",y1,st); }
        e.iter=it; g_v28_ev[g_v28_n++]=e;
    }
    if(f) fclose(f);
    g_v28_active=g_v28_n>0u;
    fprintf(stderr,"TRACE v28_script path=%s events=%u\n",path,g_v28_n);
}
