/* Deterministic native-loop snapshots are taken only at the original game()
   turn-test boundary (0x928B5). The host pointers/callbacks are deliberately
   excluded; restore rebinds them to the freshly initialized VFS. */
typedef struct gw_native_snapshot_header {
    char magic[8];
    uint32_t version, guest_size, turn, descriptor_count, dos_block_count;
    uint32_t dispatch_hit_count;
    uint32_t active_file_count;
    gw_recomp_context context;
    gw_dos_services dos;
    struct {
        char path[260];
        uint32_t position, reads, eof_reads;
        uint8_t slot, access_mode, created, dos_handle, capture_rnc;
        uint8_t reserved[3];
    } files[GW_DOS_MAX_OPEN_FILES];
    uint8_t dac[768];
} gw_native_snapshot_header;
static const char *g_snapshot_save_path;
static const char *g_snapshot_load_path;
static int g_cli_live_projection_mesh_capture;
static uint32_t g_snapshot_turn;
static int g_snapshot_save_succeeded;

static void snapshot_clear_host_pointers(gw_dos_services *d) {
    d->descriptors=NULL; d->dos_blocks=NULL;
    d->guest_memory_prepare=NULL; d->guest_memory_prepare_user=NULL;
    d->file_open=NULL; d->file_read=NULL; d->file_create=NULL;
    d->file_write=NULL; d->file_close=NULL; d->file_ioctl_info=NULL;
    d->file_seek=NULL; d->file_user=NULL;
    d->real_mode_interrupt=NULL; d->real_mode_interrupt_user=NULL;
    for(unsigned i=0;i<GW_DOS_MAX_OPEN_FILES;i++) d->files[i].file=NULL;
    for(unsigned i=0;i<3u;i++) { d->streams[i].read=NULL; d->streams[i].write=NULL; d->streams[i].user=NULL; }
}

static int native_snapshot_save(const char *path,uint8_t *memory,
        gw_dos_services *dos,const gw_recomp_context *context,uint32_t turn) {
    if(!path || !*path || !memory || !dos || !context) return 0;
    if(context->eip!=0x000928B5u ||
       *(uint32_t *)(memory+0x002F1472u)!=turn) {
        fprintf(stderr,"TRACE native_snapshot_reject reason=turn_boundary context_eip=%08x guest_Turn=%u requested=%u\n",
            context->eip,*(uint32_t *)(memory+0x002F1472u),turn);
        return 0;
    }
    gw_native_snapshot_header h; memset(&h,0,sizeof h);
    memcpy(h.magic,"GWSNAP2",7); h.version=2u; h.guest_size=GUEST_LIMIT;
    h.turn=turn; h.descriptor_count=dos->descriptor_count;
    h.dos_block_count=dos->dos_block_count; h.context=*context;
    h.context.eip=0x00092860u; h.context.cur_func=0x00092860u;
    h.context.mem_base=0; h.context.mem_guest_base=0; h.context.mem_size=GUEST_LIMIT;
    h.dos=*dos; snapshot_clear_host_pointers(&h.dos);
    for(unsigned i=0;i<GW_DOS_MAX_OPEN_FILES;i++) if(dos->files[i].active) {
        host_file *file=(host_file *)dos->files[i].file;
        long pos=(file && file->fp)?ftell(file->fp):-1L;
        if(!file || !file->fp || pos<0 || dos->files[i].created ||
           !file->path[0] || h.active_file_count>=GW_DOS_MAX_OPEN_FILES) {
            fprintf(stderr,"TRACE native_snapshot_reject reason=unserializable_dos_handle slot=%u dos_handle=%u\n",
                i,dos->files[i].dos_handle);
            return 0;
        }
        unsigned n=h.active_file_count++;
        strncpy(h.files[n].path,file->path,sizeof h.files[n].path-1u);
        h.files[n].position=(uint32_t)pos; h.files[n].reads=file->reads;
        h.files[n].eof_reads=file->eof_reads; h.files[n].slot=(uint8_t)i;
        h.files[n].access_mode=dos->files[i].access_mode;
        h.files[n].created=dos->files[i].created;
        h.files[n].dos_handle=dos->files[i].dos_handle;
        h.files[n].capture_rnc=(uint8_t)file->capture_rnc;
    }
    memcpy(h.dac,vga_dac,sizeof h.dac);
    h.dispatch_hit_count=gw_recomp_dispatch_hits_count();
    gw_recomp_dispatch_hit_snapshot_row *hit_rows=h.dispatch_hit_count?
        (gw_recomp_dispatch_hit_snapshot_row *)malloc(
            (size_t)h.dispatch_hit_count*sizeof *hit_rows):NULL;
    if((h.dispatch_hit_count && !hit_rows) ||
       !gw_recomp_dispatch_hits_export(hit_rows,h.dispatch_hit_count,
                                       &h.dispatch_hit_count)) {
        free(hit_rows); return 0;
    }
    FILE *f=fopen(path,"wb"); if(!f) { free(hit_rows); return 0; }
    int ok=fwrite(&h,sizeof h,1,f)==1 &&
        (!h.dispatch_hit_count || fwrite(hit_rows,sizeof *hit_rows,
            h.dispatch_hit_count,f)==h.dispatch_hit_count) &&
        (!h.descriptor_count || fwrite(dos->descriptors,sizeof *dos->descriptors,h.descriptor_count,f)==h.descriptor_count) &&
        (!h.dos_block_count || fwrite(dos->dos_blocks,sizeof *dos->dos_blocks,h.dos_block_count,f)==h.dos_block_count) &&
        fwrite(memory,1,GUEST_LIMIT,f)==GUEST_LIMIT;
    if(fclose(f)!=0) ok=0;
    free(hit_rows);
    return ok;
}

static int native_snapshot_load(const char *path,uint8_t *memory,
        gw_dos_services *dos,gw_recomp_context *context,uint32_t *turn_out) {
    if(!path || !*path || !memory || !dos || !context) return 0;
    FILE *f=fopen(path,"rb"); if(!f) return 0;
    gw_native_snapshot_header h; memset(&h,0,sizeof h);
    int ok=fread(&h,sizeof h,1,f)==1 && !memcmp(h.magic,"GWSNAP2",7) &&
        h.version==2u && h.guest_size==GUEST_LIMIT && h.turn>=1u &&
        h.context.eip==0x00092860u && h.descriptor_count<=65536u &&
        h.dos_block_count<=65536u && h.dispatch_hit_count<=32768u &&
        h.active_file_count<=GW_DOS_MAX_OPEN_FILES;
    gw_recomp_dispatch_hit_snapshot_row *hit_rows=NULL;
    if(ok && h.dispatch_hit_count) {
        hit_rows=(gw_recomp_dispatch_hit_snapshot_row *)malloc(
            (size_t)h.dispatch_hit_count*sizeof *hit_rows);
        ok=hit_rows && fread(hit_rows,sizeof *hit_rows,h.dispatch_hit_count,f)==
            h.dispatch_hit_count;
    }
    gw_dos_descriptor *descriptors=NULL; gw_dos_memory_block *blocks=NULL;
    if(ok && h.descriptor_count) { descriptors=(gw_dos_descriptor *)malloc((size_t)h.descriptor_count*sizeof *descriptors); ok=descriptors && fread(descriptors,sizeof *descriptors,h.descriptor_count,f)==h.descriptor_count; }
    if(ok && h.dos_block_count) { blocks=(gw_dos_memory_block *)malloc((size_t)h.dos_block_count*sizeof *blocks); ok=blocks && fread(blocks,sizeof *blocks,h.dos_block_count,f)==h.dos_block_count; }
    if(ok) ok=fread(memory,1,GUEST_LIMIT,f)==GUEST_LIMIT;
    if(fclose(f)!=0) ok=0;
    if(!ok) { free(hit_rows); free(descriptors); free(blocks); return 0; }
    /* Keep callbacks and VFS-owned handles from the fresh process, restoring
       only deterministic DOS scalar/guest-visible allocator state. */
    gw_dos_services live=*dos; gw_dos_services restored=h.dos;
    restored.descriptors=descriptors; restored.descriptor_capacity=h.descriptor_count;
    restored.dos_blocks=blocks; restored.dos_block_capacity=h.dos_block_count;
    restored.guest_memory_prepare=live.guest_memory_prepare;
    restored.guest_memory_prepare_user=live.guest_memory_prepare_user;
    restored.file_open=live.file_open; restored.file_read=live.file_read;
    restored.file_create=live.file_create; restored.file_write=live.file_write;
    restored.file_close=live.file_close; restored.file_ioctl_info=live.file_ioctl_info;
    restored.file_seek=live.file_seek; restored.file_user=live.file_user;
    restored.real_mode_interrupt=live.real_mode_interrupt;
    restored.real_mode_interrupt_user=live.real_mode_interrupt_user;
    memcpy(restored.streams,live.streams,sizeof restored.streams);
    memset(restored.files,0,sizeof restored.files);
    for(unsigned i=0;i<GW_DOS_MAX_OPEN_FILES;i++) if(live.files[i].active &&
        live.files[i].file && live.file_close)
        (void)live.file_close(live.file_user,live.files[i].file);
    for(unsigned n=0;n<h.active_file_count;n++) {
        const unsigned slot=h.files[n].slot;
        if(slot>=GW_DOS_MAX_OPEN_FILES || !h.files[n].path[0]) {
            free(hit_rows); return 0;
        }
        void *file=NULL;
        uint32_t restored_position=0u;
        uint16_t dos_error=h.files[n].created?
            (restored.file_create?restored.file_create(restored.file_user,
                h.files[n].path,0u,&file):5u):
            (restored.file_open?restored.file_open(restored.file_user,
                h.files[n].path,h.files[n].access_mode,&file):5u);
        if(dos_error || !file || !restored.file_seek ||
           restored.file_seek(restored.file_user,file,
                (int32_t)h.files[n].position,0u,&restored_position)!=0u ||
           restored_position!=h.files[n].position) {
            if(file && restored.file_close)
                (void)restored.file_close(restored.file_user,file);
            free(hit_rows); return 0;
        }
        host_file *host=(host_file *)file;
        host->capture_rnc=h.files[n].capture_rnc;
        host->reads=h.files[n].reads; host->eof_reads=h.files[n].eof_reads;
        restored.files[slot].file=file;
        restored.files[slot].access_mode=h.files[n].access_mode;
        restored.files[slot].active=1u;
        restored.files[slot].created=h.files[n].created;
        restored.files[slot].dos_handle=h.files[n].dos_handle;
    }
    free(live.descriptors); free(live.dos_blocks);
    *dos=restored; *context=h.context;
    context->mem_base=(ptrdiff_t)(uintptr_t)memory;
    context->mem_guest_base=0; context->mem_size=GUEST_LIMIT;
    memcpy(vga_dac,h.dac,sizeof vga_dac);
    if(*(uint32_t *)(memory+0x002F1472u)!=h.turn ||
       !gw_recomp_dispatch_hits_import(hit_rows,h.dispatch_hit_count)) {
        free(hit_rows); return 0;
    }
    free(hit_rows);
    if(turn_out) *turn_out=h.turn;
    return 1;
}

