static int run_panorama_draw_pass(const uint8_t *base,uint8_t *scratch,
                                  int16_t horizontal_camera_delta,unsigned shift_mask,
                                  panorama_draw_result *out) {
    if(!base||!scratch||!out) return 0;
    memset(out,0,sizeof *out);
    memcpy(scratch,base,GUEST_LIMIT);
    const uint32_t map=0x00346D70u;
    const uint32_t wscreen=*(const uint32_t *)(scratch+0x00376A5Cu);
    if(!wscreen || wscreen>GUEST_LIMIT || 640u*480u>GUEST_LIMIT-wscreen || map+0x20u>GUEST_LIMIT)
        return 0;
    /* Test the original map coordinates independently. Moving +0x08 and
       +0x1D together preserved the image exactly and did not pan the world. */
    const int16_t view_start=(int16_t)*(uint16_t *)(scratch+map+0x08u);
    const int16_t view_origin=(int16_t)*(uint16_t *)(scratch+map+0x1Du);
    if(shift_mask&1u) *(int16_t *)(scratch+map+0x08u)=(int16_t)(view_start-horizontal_camera_delta);
    if(shift_mask&2u) *(int16_t *)(scratch+map+0x1Du)=(int16_t)(view_origin-horizontal_camera_delta);
    else if(shift_mask&4u) *(int16_t *)(scratch+map+0x1Du)=(int16_t)(view_origin+horizontal_camera_delta);
    /* +0x10/+0x12 carry the MapDisplay world-space camera center.  Move the
       two isometric world axes in opposite directions; unlike +0x08/+0x1D,
       which affect the terrain clip/start bookkeeping, these are the camera
       coordinates used by world projection. */
    if(shift_mask&8u) *(int16_t *)(scratch+map+0x10u)=(int16_t)(*(int16_t *)(scratch+map+0x10u)-horizontal_camera_delta);
    if(shift_mask&16u) *(int16_t *)(scratch+map+0x12u)=(int16_t)(*(int16_t *)(scratch+map+0x12u)+horizontal_camera_delta);
    /* 0x7C610 consumes and clears the MapDisplay dirty-row list.  Start every
       isolated camera pass with all 20 row entries set. The global redraw bit
       alone does not make the row loop at 0x7C671 call 0x7C230. This explicitly
       requests a full world redraw on the private clone only. */
    scratch[map+0x1Cu]|=0x02u;
    memset(scratch+map+0x11BDu,1u,20u);
    out->wscreen=wscreen;
    out->width=640u; out->height=480u;
    out->map_x=*(int16_t *)(scratch+map+8u);
    out->map_y=*(int16_t *)(scratch+map+10u);
    out->camera_target_x=*(int16_t *)(scratch+map+0x08u);
    out->camera_target_y=*(int16_t *)(scratch+map+0x1Du);
    out->map_center_x=*(int16_t *)(scratch+map+16u);
    out->map_center_y=*(int16_t *)(scratch+map+18u);
    out->map_left=*(int16_t *)(scratch+map+0x1Du);
    out->map_right=(int16_t)(*(int16_t *)(scratch+map+8u));
    out->map_view_width=scratch[map+0x33u];
    out->map_view_rows=scratch[map+0x35u];
    out->map_view_mode=scratch[map+0x0Du];
    out->map_view_flags=scratch[map+0x1Cu];
    out->camera_x=(int16_t)*(uint16_t *)(scratch+map+0x10u);
    out->camera_y=(int16_t)*(uint16_t *)(scratch+map+0x12u);
    out->video_width=*(uint32_t *)(scratch+0x00376A78u);
    out->video_height=*(uint32_t *)(scratch+0x00376A7Cu);
    out->window_x=*(uint32_t *)(scratch+0x00376A80u);
    uint8_t saved_dac[sizeof vga_dac]; memcpy(saved_dac,vga_dac,sizeof saved_dac);
    double saved_st[8]; memcpy(saved_st,g_st,sizeof saved_st);
    const int saved_fp_top=g_fp_top; const uint16_t saved_fpu_cw=g_fpu_cw;
    const ptrdiff_t saved_mem_base=g_mem_base; uint8_t *saved_guest=guest_memory;
    const uint32_t saved_icall_count=g_icall_count,saved_icall_idx=g_icall_trace_idx;
    uint32_t *saved_trace=(uint32_t *)malloc(sizeof g_icall_trace+sizeof g_icall_from);
    uint32_t saved_draw_target=g_ifclevel_draw_dispatch_target;
    uint32_t saved_draw_caller=g_ifclevel_draw_dispatch_caller;
    uint32_t saved_draw_calls=g_ifclevel_draw_dispatch_count;
    if(!saved_trace) return 0;
    memcpy(saved_trace,g_icall_trace,sizeof g_icall_trace);
    memcpy(saved_trace+ICALL_TRACE_SIZE,g_icall_from,sizeof g_icall_from);
    guest_memory=scratch; g_mem_base=(ptrdiff_t)(uintptr_t)scratch;
    if(g_hybrid_clear_surface) memset(scratch+wscreen,0,640u*480u);
    g_ifclevel_draw_dispatch_target=0; g_ifclevel_draw_dispatch_caller=0;
    g_ifclevel_draw_dispatch_count=0;
    const uint32_t calls_before=g_icall_count;
    gw_recomp_context c;
    /* Bypass draw_game's once-per-frame gate.  A private panorama pass is a
       renderer diagnostic, not another simulation frame; enter the original
       MapDisplay::Draw method with the same receiver the IFC passes to it. */
    if(g_hybrid_use_game_draw)
        out->invoke_ok=invoke(gw_original_draw_game_draw_dispatch,&c,0x83559u,scratch,0,0);
    else
        out->invoke_ok=invoke(gw_partial_0x0007C610,&c,0x7C610u,scratch,map,0);
    out->end_eip=c.eip;
    out->fault=c.memory_fault.pending||c.segment_fault_pending||c.interrupt_trap_pending||c.port_io_trap.pending;
    out->draw_target=out->invoke_ok?(g_hybrid_use_game_draw?g_ifclevel_draw_dispatch_target:0x7C610u):0u;
    out->draw_calls=out->invoke_ok?(g_hybrid_use_game_draw?g_ifclevel_draw_dispatch_count:1u):0u;
    out->callsite_count=g_icall_count-calls_before;
    if(out->invoke_ok&&!out->fault&&out->draw_target!=0u&&out->draw_calls==1u) {
        out->pixels=(uint8_t *)malloc(640u*480u);
        if(out->pixels) memcpy(out->pixels,scratch+wscreen,640u*480u);
    }
    if(out->pixels) {
        for(uint32_t i=0;i<GUEST_LIMIT;i++)
            if((i<wscreen || i>=wscreen+640u*480u) && scratch[i]!=base[i])
                out->changed_outside_wscreen++;
    }
    memcpy(vga_dac,saved_dac,sizeof saved_dac);
    memcpy(g_st,saved_st,sizeof saved_st); g_fp_top=saved_fp_top; g_fpu_cw=saved_fpu_cw;
    memcpy(g_icall_trace,saved_trace,sizeof g_icall_trace);
    memcpy(g_icall_from,saved_trace+ICALL_TRACE_SIZE,sizeof g_icall_from); free(saved_trace);
    g_icall_count=saved_icall_count; g_icall_trace_idx=saved_icall_idx;
    g_ifclevel_draw_dispatch_target=saved_draw_target;
    g_ifclevel_draw_dispatch_caller=saved_draw_caller;
    g_ifclevel_draw_dispatch_count=saved_draw_calls;
    g_mem_base=saved_mem_base; guest_memory=saved_guest;
    return out->pixels!=NULL;
}

static int run_original_draw_with_widened_surface(const uint8_t *base,
        uint8_t *scratch,unsigned width,unsigned height,const uint8_t *seed640,
        panorama_draw_result *out) {
    if(!base||!scratch||!out||width<=640u||height!=480u) return 0;
    memset(out,0,sizeof *out);
    memcpy(scratch,base,GUEST_LIMIT);
    const uint32_t old_wscreen=*(const uint32_t *)(scratch+0x00376A5Cu);
    const size_t bytes=(size_t)width*height;
    if(!old_wscreen||old_wscreen>GUEST_LIMIT||307200u>GUEST_LIMIT-old_wscreen) return 0;
    uint32_t candidate=(old_wscreen+307200u+4095u)&~4095u;
    for(;candidate<=GUEST_LIMIT-bytes;candidate+=4096u) {
        size_t i=0; while(i<bytes&&scratch[candidate+i]==0u) i++;
        if(i==bytes) break;
    }
    if(candidate>GUEST_LIMIT-bytes || candidate+bytes+32u>GUEST_LIMIT) return 0;
    uint8_t tail_canary[32]; memset(tail_canary,0xA7,sizeof tail_canary);
    memcpy(scratch+candidate+bytes,tail_canary,sizeof tail_canary);
    if(g_wide_probe_active) {
        g_wide_probe_base=candidate;
        g_wide_probe_width=width;
    }
    if(seed640) for(unsigned y=0;y<height;y++) {
        memcpy(scratch+candidate+y*width,seed640+y*640u,640u);
        memset(scratch+candidate+y*width+640u,0,width-640u);
    }
    const uint32_t map=0x00346D70u;
    out->wscreen=candidate; out->width=(uint16_t)width; out->height=(uint16_t)height;
    out->map_x=*(int16_t *)(scratch+map+8u); out->map_y=*(int16_t *)(scratch+map+10u);
    *(uint32_t *)(scratch+0x00376A5Cu)=candidate;
    *(uint32_t *)(scratch+0x00376A78u)=width;
    *(uint32_t *)(scratch+0x00376A7Cu)=height;
    /* 0x376A80 is WINDOW_X, not a framebuffer pitch.  The renderer's
       software-vector setup stores its pitch and clipping width in the
       setup_vecs state at 0x002DA100. Match setup_vecs(candidate, 0, width,
       width, height) on this private snapshot; changing only WScreen and the
       dimensions leaves the original 640-byte vector pitch in effect. */
    const uint32_t vec=0x002DA100u;
    if(vec+0x24u>GUEST_LIMIT) return 0;
    *(uint32_t *)(scratch+vec+0x00u)=candidate-width;
    *(uint32_t *)(scratch+vec+0x04u)=candidate;
    *(uint32_t *)(scratch+vec+0x10u)=width;
    *(uint32_t *)(scratch+vec+0x14u)=width;
    *(uint32_t *)(scratch+vec+0x18u)=height;
    /* A snapshot can have no dirty terrain rows. Request the same complete
       MapDisplay redraw used by the 640 control pass on this private clone. */
    scratch[map+0x1Cu]|=0x02u;
    memset(scratch+map+0x11BDu,1u,20u);
    out->vector_poly_base=*(uint32_t *)(scratch+vec+0x00u);
    out->vector_pitch=*(uint32_t *)(scratch+vec+0x10u);
    out->vector_clip_width=*(uint32_t *)(scratch+vec+0x14u);
    out->vector_height=*(uint32_t *)(scratch+vec+0x18u);
    uint8_t saved_dac[sizeof vga_dac]; memcpy(saved_dac,vga_dac,sizeof saved_dac);
    double saved_st[8]; memcpy(saved_st,g_st,sizeof saved_st);
    const int saved_fp_top=g_fp_top; const uint16_t saved_fpu_cw=g_fpu_cw;
    const ptrdiff_t saved_mem_base=g_mem_base; uint8_t *saved_guest=guest_memory;
    const uint32_t saved_icall_count=g_icall_count,saved_icall_idx=g_icall_trace_idx;
    uint32_t *saved_trace=(uint32_t *)malloc(sizeof g_icall_trace+sizeof g_icall_from);
    uint32_t saved_draw_target=g_ifclevel_draw_dispatch_target;
    uint32_t saved_draw_caller=g_ifclevel_draw_dispatch_caller;
    uint32_t saved_draw_calls=g_ifclevel_draw_dispatch_count;
    if(!saved_trace) return 0;
    memcpy(saved_trace,g_icall_trace,sizeof g_icall_trace);
    memcpy(saved_trace+ICALL_TRACE_SIZE,g_icall_from,sizeof g_icall_from);
    guest_memory=scratch; g_mem_base=(ptrdiff_t)(uintptr_t)scratch;
    g_ifclevel_draw_dispatch_target=0; g_ifclevel_draw_dispatch_caller=0;
    g_ifclevel_draw_dispatch_count=0;
    const uint32_t calls_before=g_icall_count;
    gw_recomp_context c;
    out->invoke_ok=invoke(gw_partial_0x0007C610,&c,0x7C610u,scratch,map,0);
    out->end_eip=c.eip;
    out->fault=c.memory_fault.pending||c.segment_fault_pending||c.interrupt_trap_pending||c.port_io_trap.pending;
    out->draw_target=out->invoke_ok?0x7C610u:0u;
    out->draw_calls=out->invoke_ok?1u:0u;
    out->callsite_count=g_icall_count-calls_before;
    for(unsigned i=0;i<sizeof tail_canary;i++)
        out->tail_canary_overwrites += scratch[candidate+bytes+i]!=tail_canary[i];
    if(out->invoke_ok&&!out->fault) {
        out->pixels=(uint8_t *)malloc(bytes);
        if(out->pixels) memcpy(out->pixels,scratch+candidate,bytes);
    }
    if(out->pixels) for(uint32_t i=0;i<GUEST_LIMIT;i++)
        if((i<candidate||i>=candidate+bytes)&&scratch[i]!=base[i])
            out->changed_outside_wscreen++;
    memcpy(vga_dac,saved_dac,sizeof saved_dac);
    memcpy(g_st,saved_st,sizeof saved_st); g_fp_top=saved_fp_top; g_fpu_cw=saved_fpu_cw;
    memcpy(g_icall_trace,saved_trace,sizeof g_icall_trace);
    memcpy(g_icall_from,saved_trace+ICALL_TRACE_SIZE,sizeof g_icall_from); free(saved_trace);
    g_icall_count=saved_icall_count; g_icall_trace_idx=saved_icall_idx;
    g_ifclevel_draw_dispatch_target=saved_draw_target;
    g_ifclevel_draw_dispatch_caller=saved_draw_caller;
    g_ifclevel_draw_dispatch_count=saved_draw_calls;
    g_mem_base=saved_mem_base; guest_memory=saved_guest;
    return out->pixels!=NULL;
}

/* ---- True widescreen 854x480 (original renderer on a 864-pixel surface; 27 strips of 32 px) ----------------
   The lifted closure carries the widescreen rules of tools/lift_entry_path.py (strip count, y*width, strip dirty
   bytes >= 20 outside MapDisplay, 20-column cell grid kept, camera centre at the 640 frame). After the original
   dirty-cell copy (0x1CAE0) the band x=640..W-1 is copied whole from the map ring buffer here, with the ring
   mapping of 0x1C600: screen (x,y) <- ring (left + ((x-left) + (ring_x-left)) mod (W-left), (y + ring_y) mod H),
   left = MapDisplay+0x1D, ring_x = +0x08, ring_y = +0x0A. */
extern uint32_t g_gw_ws_strip_ext;
extern void (*g_gw_ws_band_copy)(void);
static uint32_t g_ws_band_copies;
static int ws_ring_source(const uint8_t *m,uint32_t width,uint32_t height,uint32_t x,uint32_t y,uint32_t *at) {
    const uint32_t map=0x00346D70u;
    const int left=(int)*(const uint16_t *)(m+map+0x1Du);
    const int ring_x=(int)*(const int16_t *)(m+map+0x08u),ring_y=(int)*(const int16_t *)(m+map+0x0Au);
    const int ring_w=(int)width-left;
    if(ring_w<=0 || (int)x<left) return 0;
    int rx=((int)x-left)+(ring_x-left); rx%=ring_w; if(rx<0) rx+=ring_w;
    int ry=((int)y+ring_y)%(int)height; if(ry<0) ry+=(int)height;
    *at=(uint32_t)ry*width+(uint32_t)(left+rx);
    return 1;
}
static void ws_band_copy_impl(void) {
    uint8_t *m=guest_memory; if(!m) return;
    const uint32_t width=*(const uint32_t *)(m+0x00376A78u),height=*(const uint32_t *)(m+0x00376A7Cu);
    if(width<=640u || width>1024u || height!=480u) return;
    const uint32_t ws=*(const uint32_t *)(m+0x00376A5Cu),ring=*(const uint32_t *)(m+0x002EECA0u);
    const uint32_t bytes=width*height;
    if(!ws || !ring || ws>GUEST_LIMIT-bytes || ring>GUEST_LIMIT-bytes) return;
    /* Row copies: the band x=640..W-1 maps to one contiguous ring run per row, split once at the ring's wrap. */
    const uint32_t map=0x00346D70u;
    const int left=(int)*(const uint16_t *)(m+map+0x1Du);
    const int ring_x=(int)*(const int16_t *)(m+map+0x08u),ring_y=(int)*(const int16_t *)(m+map+0x0Au);
    const int ring_w=(int)width-left;
    if(ring_w<=0 || left>640) return;
    int rx0=(640-left)+(ring_x-left); rx0%=ring_w; if(rx0<0) rx0+=ring_w;
    const uint32_t band=width-640u;
    const uint32_t first=(uint32_t)(ring_w-rx0)<band?(uint32_t)(ring_w-rx0):band;
    for(uint32_t y=0;y<height;y++) {
        int ry=((int)y+ring_y)%(int)height; if(ry<0) ry+=(int)height;
        const uint8_t *src=m+ring+(uint32_t)ry*width+(uint32_t)left;
        uint8_t *dst=m+ws+y*width+640u;
        memcpy(dst,src+rx0,first);
        if(first<band) memcpy(dst+first,src,band-first);
    }
    g_ws_band_copies++;
}

typedef struct {
    int ok,invoke_ok,fault; uint32_t end_eip,changed_outside,canary_overwrites;
    uint8_t *pixels; uint32_t width,ring,flags;
} ws_pass;

/* One private MapDisplay::Draw (full redraw) on a clone of `base` at surface width `width` (640 = canonical,
   untouched surface and buffers). Wider surfaces get a fresh WScreen, map ring buffer and strip-flag block in the
   DPMI address space above the allocator cursor (never granted, so no live block or MCB can be there). */
static int ws_run_pass(const uint8_t *base,uint8_t *scratch,const gw_dos_services *dos,uint32_t width,ws_pass *out,
                       uint32_t *alloc_base,uint32_t *alloc_size,uint8_t strip_level,int clear_ring) {
    memset(out,0,sizeof *out); out->width=width;
    memcpy(scratch,base,GUEST_LIMIT);
    /* GWRECOMP_WS854_SHIFT_CELLS=n moves the projection origin (link 0x184AAC/0x184AB0: map column/row of
       strip 0) n cells along the screen-x diagonal on this clone, so Things that sit inside the 640 frame
       are drawn n*64 px further right (into the widescreen band). Same shift for every pass of a probe. */
    {   const char *sh=getenv("GWRECOMP_WS854_SHIFT_CELLS");
        const int n=sh&&sh[0]?atoi(sh):0;
        /* Terrain projects from the origin cell; Things from the MapDisplay world camera (+0x10/+0x12, 256 world
           units per cell). Move both along the same diagonal so terrain and Things stay consistent. */
        if(n) { *(int32_t *)(scratch+0x0035EAACu)-=n; *(int32_t *)(scratch+0x0035EAB0u)+=n;
            *(int16_t *)(scratch+0x00346D70u+0x10u)-=(int16_t)(n*256); *(int16_t *)(scratch+0x00346D70u+0x12u)+=(int16_t)(n*256); } }
    const uint32_t map=0x00346D70u,height=480u,bytes=width*height,guard=64u;
    uint32_t ws=*(const uint32_t *)(scratch+0x00376A5Cu),ring=*(const uint32_t *)(scratch+0x002EECA0u),flags=0u;
    uint32_t lo=0u,hi=0u;
    if(width!=640u) {
        /* The DPMI range is fully granted to the guest CRT at start-up (cursor == end), so the buffers come from
           the game's own block allocator 0x91E00, the routine that allocated the 640x480 ring at 0x92B7D. */
        (void)dos;
        const uint32_t sizes[3]={bytes+guard,bytes+guard,64u};
        uint32_t got[3]={0,0,0};
        for(unsigned k=0;k<3u;k++) {
            gw_recomp_context ac;
            const ptrdiff_t smb=g_mem_base; uint8_t *sg=guest_memory;
            guest_memory=scratch; g_mem_base=(ptrdiff_t)(uintptr_t)scratch;
            const int aok=invoke(gw_partial_0x00091E00,&ac,0x91E00u,scratch,sizes[k],0);
            g_mem_base=smb; guest_memory=sg;
            if(!aok || !ac.eax || ac.eax>GUEST_LIMIT-sizes[k]) return 0;
            got[k]=ac.eax;
        }
        ws=got[0]; ring=got[1]; flags=got[2];
        lo=ws; hi=ws+sizes[0];
        if(alloc_base) *alloc_base=ws;
        if(alloc_size) *alloc_size=sizes[0];
        out->ring=ring; out->flags=flags;
        /* Seed the new WScreen with the current 640 frame (HUD x<176 is drawn by other IFC code, not by
           MapDisplay::Draw) and a black band; the ring starts black (Draw redraws every strip). */
        const uint32_t old_ws=*(const uint32_t *)(base+0x00376A5Cu);
        if(!old_ws || old_ws>GUEST_LIMIT-640u*480u) return 0;
        for(uint32_t y=0;y<height;y++) {
            memcpy(scratch+ws+y*width,base+old_ws+y*640u,640u);
            memset(scratch+ws+y*width+640u,0,width-640u);
        }
        /* The ring also carries the HUD columns that the dirty-cell copy (0x1CAE0) restores: start it as the
           current 640 ring, widened (Draw redraws every map strip). */
        const uint32_t old_ring=*(const uint32_t *)(base+0x002EECA0u);
        if(!old_ring || old_ring>GUEST_LIMIT-640u*480u) return 0;
        for(uint32_t y=0;y<height;y++) {
            const uint32_t hud=*(const uint16_t *)(scratch+map+0x1Du);
            memset(scratch+ring+y*width,0,width);
            memcpy(scratch+ring+y*width,base+old_ring+y*640u,hud<=640u?hud:640u);
        }
        memset(scratch+ws+bytes,0xA7,guard); memset(scratch+ring+bytes,0xA7,guard);
        *(uint32_t *)(scratch+0x00376A5Cu)=ws;
        *(uint32_t *)(scratch+0x00376A78u)=width;
        *(uint32_t *)(scratch+0x00376A7Cu)=height;
        *(uint32_t *)(scratch+0x002EECA0u)=ring;
        /* setup_vecs (0xE8963) state: poly base, base, pitch, clip width, height (it keeps the pitch it was
           given at mode setup, so the strip windows inherit it). */
        const uint32_t vec=0x002DA100u;
        *(uint32_t *)(scratch+vec+0x00u)=ws-width; *(uint32_t *)(scratch+vec+0x04u)=ws;
        *(uint32_t *)(scratch+vec+0x10u)=width; *(uint32_t *)(scratch+vec+0x14u)=width; *(uint32_t *)(scratch+vec+0x18u)=height;
        /* MapDisplay+0x33 is the ring split (0x7A099: width - ring_x), recomputed by the scroll path. */
        *(uint16_t *)(scratch+map+0x33u)=(uint16_t)(width-*(const uint16_t *)(scratch+map+0x08u));
        memset(scratch+flags,strip_level,16u);
    }
    scratch[map+0x1Cu]|=0x02u;
    /* Strip dirty bytes are levels (callers store max(old,new)): 1 = partial redraw through 0x665B0,
       higher = whole strip through 0x65F20. */
    memset(scratch+map+0x11BDu,strip_level,20u);
    if(width==640u && clear_ring) {
        const uint32_t hud=*(const uint16_t *)(scratch+map+0x1Du);
        for(uint32_t y=0;y<height;y++) memset(scratch+ring+y*640u+hud,0,640u-hud);
    }
    uint8_t saved_dac[sizeof vga_dac]; memcpy(saved_dac,vga_dac,sizeof saved_dac);
    double saved_st[8]; memcpy(saved_st,g_st,sizeof saved_st);
    const int saved_fp_top=g_fp_top; const uint16_t saved_fpu_cw=g_fpu_cw;
    const ptrdiff_t saved_mem_base=g_mem_base; uint8_t *saved_guest=guest_memory;
    guest_memory=scratch; g_mem_base=(ptrdiff_t)(uintptr_t)scratch;
    g_gw_ws_strip_ext=flags; g_gw_ws_band_copy=width!=640u?ws_band_copy_impl:NULL;
    gw_recomp_context c;
    /* GWRECOMP_WS854_GAME_DRAW=1: the whole original draw_game dispatch (map, Things, HUD) instead of only
       MapDisplay::Draw, which draws terrain but no entities. */
    const char *gd=getenv("GWRECOMP_WS854_GAME_DRAW");
    if(gd && gd[0]=='1') out->invoke_ok=invoke(gw_original_draw_game_draw_dispatch,&c,0x83559u,scratch,0,0);
    else out->invoke_ok=invoke(gw_partial_0x0007C610,&c,0x7C610u,scratch,map,0);
    out->end_eip=c.eip;
    out->fault=c.memory_fault.pending||c.segment_fault_pending||c.interrupt_trap_pending||c.port_io_trap.pending;
    g_gw_ws_strip_ext=0u; g_gw_ws_band_copy=NULL;
    memcpy(vga_dac,saved_dac,sizeof saved_dac);
    memcpy(g_st,saved_st,sizeof saved_st); g_fp_top=saved_fp_top; g_fpu_cw=saved_fpu_cw;
    g_mem_base=saved_mem_base; guest_memory=saved_guest;
    if(width!=640u) for(uint32_t i=0;i<guard;i++)
        out->canary_overwrites+=(scratch[ws+bytes+i]!=0xA7u)+(scratch[ring+bytes+i]!=0xA7u);
    for(uint32_t i=0;i<GUEST_LIMIT;i++) {
        if(i>=lo && i<hi) continue;
        if(width!=640u && ((i>=ring && i<ring+bytes+guard) || (i>=flags && i<flags+64u))) continue;
        if(width==640u && i>=ws && i<ws+bytes) continue;
        if(width==640u && clear_ring && i>=ring && i<ring+bytes) continue;
        out->changed_outside+=(scratch[i]!=base[i]);
    }
    if(out->invoke_ok && !out->fault) {
        out->pixels=(uint8_t *)malloc(bytes);
        if(out->pixels) memcpy(out->pixels,scratch+ws,bytes);
    }
    out->ok=out->pixels!=NULL;
    return out->ok;
}

static int run_widescreen_854_probe(uint8_t *memory,const gw_dos_services *dos,uint16_t dos_segment_end) {
    uint8_t *scratch=(uint8_t *)malloc(GUEST_LIMIT); if(!scratch) return 0;
    ws_pass c640,full640,wide; uint32_t alloc_base=0,alloc_size=0;
    const uint32_t W=864u,H=480u,OUTW=854u;
    const int a=ws_run_pass(memory,scratch,dos,640u,&c640,NULL,NULL,1u,0);
    const int mcb640=validate_dos_mcb_chain(scratch,dos_segment_end);
    /* Whole-strip redraw at 640 from an empty ring: shows the level-2 path rebuilds the canonical frame. */
    const int f=ws_run_pass(memory,scratch,dos,640u,&full640,NULL,NULL,2u,1);
    unsigned full_equal=0;
    if(a&&f) for(uint32_t i=0;i<640u*480u;i++) full_equal+=(c640.pixels[i]==full640.pixels[i]);
    if(f) { char fp[160]; snprintf(fp,sizeof fp,"evidence/ws854_t%u_full640_640x480.bmp",*(uint32_t *)(memory+0x002F1472u));
        (void)save_indexed_bmp24(fp,full640.pixels,640u,480u,vga_dac); }
    g_ws_band_copies=0;
    const int b=ws_run_pass(memory,scratch,dos,W,&wide,&alloc_base,&alloc_size,2u,1);
    const int mcb_wide=validate_dos_mcb_chain(scratch,dos_segment_end);
    /* Self-check of the ring mapping on the canonical frame: background ring pixels mapped into x=left..639. */
    unsigned map_match=0,map_tested=0,left_equal=0,band_nonzero=0,band_unique=0,band_overlay=0,band_black_cols=0;
    unsigned char seen[256]={0};
    if(b) {
        const uint32_t ring=wide.ring;
        for(uint32_t y=0;y<H;y++) for(uint32_t x=128u;x<640u;x++) {
            uint32_t at; if(!ws_ring_source(scratch,W,H,x,y,&at)) continue;
            map_tested++; map_match+=(scratch[ring+at]==wide.pixels[y*W+x]);
        }
        for(uint32_t x=640u;x<OUTW;x++) {
            unsigned col_nonzero=0;
            for(uint32_t y=0;y<H;y++) {
                const uint8_t v=wide.pixels[y*W+x]; col_nonzero+=(v!=0u);
                if(!seen[v]) { seen[v]=1; band_unique++; }
                uint32_t at; if(ws_ring_source(scratch,W,H,x,y,&at) && scratch[ring+at]!=v) band_overlay++;
            }
            band_nonzero+=col_nonzero; band_black_cols+=(col_nonzero==0u);
        }
    }
    if(a&&b) for(uint32_t y=0;y<H;y++) for(uint32_t x=0;x<640u;x++) left_equal+=(c640.pixels[y*640u+x]==wide.pixels[y*W+x]);
    uint8_t *crop=NULL;
    if(b) { crop=(uint8_t *)malloc(OUTW*H); if(crop) for(uint32_t y=0;y<H;y++) memcpy(crop+y*OUTW,wide.pixels+y*W,OUTW); }
    const unsigned turn=*(uint32_t *)(memory+0x002F1472u);
    char pth[160];
    if(b) { snprintf(pth,sizeof pth,"evidence/ws854_t%u_ring_864x480.bmp",turn); (void)save_indexed_bmp24(pth,scratch+wide.ring,W,H,vga_dac); }
    if(a) { snprintf(pth,sizeof pth,"evidence/ws854_t%u_control_640x480.bmp",turn); (void)save_indexed_bmp24(pth,c640.pixels,640u,H,vga_dac); }
    if(a) { (void)save_indexed_bmp24("evidence/ws854_control_640x480.bmp",c640.pixels,640u,H,vga_dac);
        FILE *r=fopen("evidence/ws854_control_640x480.raw","wb"); if(r) { fwrite(c640.pixels,1,640u*H,r); fclose(r); } }
    if(crop) { snprintf(pth,sizeof pth,"evidence/ws854_t%u_original_renderer_854x480.bmp",turn); (void)save_indexed_bmp24(pth,crop,OUTW,H,vga_dac); }
    if(crop) { (void)save_indexed_bmp24("evidence/ws854_original_renderer_854x480.bmp",crop,OUTW,H,vga_dac);
        FILE *r=fopen("evidence/ws854_original_renderer_854x480.raw","wb"); if(r) { fwrite(crop,1,OUTW*H,r); fclose(r); } }
    snprintf(pth,sizeof pth,"evidence/ws854_t%u_probe.json",turn);
    FILE *j=fopen(pth,"w");
    if(j) {
        fprintf(j,"{\n  \"schema\": \"gwrecomp.true-widescreen-854/v1\",\n  \"snapshot_turn\": %u,\n",*(uint32_t *)(memory+0x002F1472u));
        fprintf(j,"  \"control_640\": {\"ok\": %d, \"fault\": %d, \"end_eip\": \"0x%08X\", \"changed_guest_bytes_outside_wscreen\": %u, \"MCB_chain_valid\": %d, \"capture\": \"evidence/ws854_control_640x480.bmp\"},\n",
            c640.ok,c640.fault,c640.end_eip,c640.changed_outside,mcb640);
        fprintf(j,"  \"wide\": {\"ok\": %d, \"fault\": %d, \"end_eip\": \"0x%08X\", \"surface\": \"%ux%u\", \"output\": \"%ux%u\", \"strips\": %u, \"wscreen_block\": [\"0x%08X\", \"0x%08X\"], \"ring_block\": \"0x%08X\", \"allocator\": \"game 0x91E00\", \"canary_overwrites\": %u, \"changed_guest_bytes_outside_new_buffers\": %u, \"MCB_chain_valid\": %d, \"band_copies\": %u, \"capture\": \"evidence/ws854_original_renderer_854x480.bmp\"},\n",
            wide.ok,wide.fault,wide.end_eip,W,H,OUTW,H,(W+31u)/32u,alloc_base,alloc_base+alloc_size,wide.ring,wide.canary_overwrites,wide.changed_outside,mcb_wide,g_ws_band_copies);
        fprintf(j,"  \"full_redraw_640_from_empty_ring\": {\"ok\": %d, \"fault\": %d, \"equal_to_control_pixels\": %u},\n",full640.ok,full640.fault,full_equal);
        fprintf(j,"  \"left_640_equal_pixels\": %u, \"left_640_total\": %u,\n",left_equal,640u*H);
        fprintf(j,"  \"ring_mapping_selfcheck_x128_639\": {\"matching\": %u, \"tested\": %u},\n",map_match,map_tested);
        fprintf(j,"  \"band_x640_853\": {\"nonzero_pixels\": %u, \"total\": %u, \"unique_colors\": %u, \"all_black_columns\": %u, \"pixels_differing_from_ring_background\": %u}\n}\n",
            band_nonzero,(OUTW-640u)*H,band_unique,band_black_cols,band_overlay);
        fclose(j);
    }
    fprintf(stderr,"TRACE ws854 full640_equal=%u/%u\n",full_equal,640u*H);
    fprintf(stderr,"TRACE ws854 control_ok=%d wide_ok=%d fault=%d/%d left_equal=%u/%u band_nonzero=%u/%u black_cols=%u overlay=%u canary=%u changed=%u/%u mcb=%d/%d map_selfcheck=%u/%u\n",
        c640.ok,wide.ok,c640.fault,wide.fault,left_equal,640u*H,band_nonzero,(OUTW-640u)*H,band_black_cols,band_overlay,
        wide.canary_overwrites,c640.changed_outside,wide.changed_outside,mcb640,mcb_wide,map_match,map_tested);
    const int ok=a&&b&&!c640.fault&&!wide.fault&&mcb640&&mcb_wide&&wide.canary_overwrites==0u;
    free(crop); free(c640.pixels); free(full640.pixels); free(wide.pixels); free(scratch);
    return ok;
}

static int run_first_lateral_32_probe(uint8_t *memory) {
    uint8_t *scratch=(uint8_t *)malloc(GUEST_LIMIT);
    if(!scratch) return 0;
    panorama_draw_result canonical={0},expanded={0};
    wide_raster_site original_sites[45];
    memset(g_wide_sites,0,sizeof g_wide_sites);
    g_wide_probe_base=*(uint32_t *)(memory+0x00376A5Cu);
    g_wide_probe_width=640u; g_wide_probe_active=1u;
    const int trace_was_enabled=gw_recomp_trace_enabled();
    gw_recomp_trace_set_enabled(1);
    gw_recomp_trace_watch_branch(0x0007C27Du);
    /* Observe the active post-setup tile enumerator (0x665B0), its polygon
       admission checks, and the clipper's right-edge comparisons. */
    const uint32_t watched[]={0x668AAu,0x668CFu,0x668D4u,0x668D9u,
        0x668F1u,0x669ACu,0x669B3u,0x669BAu,0x669F1u,0x669F6u,
        0x66A39u,0x66A3Du,0x66A4Fu,0x66A59u,0x66A81u,0x66A88u,
        0x66AA0u,0x66AA7u,0x66AB8u,0x66ABFu,0x66B77u,0x66B95u,
        0x66BA6u,0x66BBCu};
    for(unsigned wi=0;wi<sizeof watched/sizeof watched[0];wi++)
        gw_recomp_trace_watch_branch(watched[wi]);
    int a=run_panorama_draw_pass(memory,scratch,0,0,&canonical);
    memcpy(original_sites,g_wide_sites,sizeof original_sites);
    memset(g_wide_sites,0,sizeof g_wide_sites);
    g_wide_force_expanded_clip=1u;
    int b=run_original_draw_with_widened_surface(memory,scratch,672u,480u,
        canonical.pixels,&expanded);
    g_wide_force_expanded_clip=0u;
    gw_recomp_trace_watch_branch(0u);
    gw_recomp_trace_set_enabled(trace_was_enabled);
    g_wide_probe_active=0u;
    unsigned equal=0,nonzero=0,unique[256]={0};
    if(a&&b) for(unsigned y=0;y<480u;y++) {
        for(unsigned x=0;x<640u;x++)
            equal+=(canonical.pixels[y*640u+x]==expanded.pixels[y*672u+x]);
        for(unsigned x=640u;x<672u;x++) {
            unsigned v=expanded.pixels[y*672u+x]; nonzero+=(v!=0u); unique[v]=1u;
        }
    }
    unsigned colors=0; for(unsigned i=0;i<256u;i++) colors+=unique[i];
    FILE *f=fopen("evidence/first_lateral_32_ecx672_intervention.json","wb");
    if(f) {
        fprintf(f,"{\n  \"schema\": \"gwrecomp.first-lateral-32-raster/v1\",\n"
            "  \"snapshot_turn\": %u, \"canonical_draw_ok\": %s, \"expanded_draw_ok\": %s,\n"
            "  \"map_display_plus_0a_word\": %u, \"map_display_fields\": {\"+0x08\": %d, \"+0x0A\": %d, \"+0x1D\": %d, \"+0x33_word\": %d, \"+0x35_word\": %d},\n"
            "  \"experimental_clip_override\": {\"enabled\": true, \"site\": \"0x7C43C\", \"from\": 640, \"to\": 672, \"scope\": \"private 672x480 renderer probe only\"},\n"
            "  \"canonical_wscreen\": %u, \"expanded_wscreen\": %u,"
            " \"expanded_pitch\": %u, \"expanded_clip\": %u, \"expanded_tail_canary_overwrites\": %u, \"expanded_changed_outside_surface_bytes\": %u,\n"
            "  \"canonical_overlap_equal_pixels\": %u, \"overlap_total\": 307200,"
            " \"right_band_nonzero_pixels\": %u, \"right_band_unique_colors\": %u,\n"
            "  \"sites\": [\n",
            *(uint32_t *)(memory+0x002F1472u),a?"true":"false",b?"true":"false",
            *(uint16_t *)(memory+0x00346D7Au),
            *(int16_t *)(memory+0x00346D78u),*(int16_t *)(memory+0x00346D7Au),
            *(int16_t *)(memory+0x00346D8Du),
            *(int16_t *)(memory+0x00346DA3u),*(int16_t *)(memory+0x00346DA5u),
            canonical.wscreen,expanded.wscreen,expanded.vector_pitch,expanded.vector_clip_width,
            expanded.tail_canary_overwrites,expanded.changed_outside_wscreen,
            equal,nonzero,colors);
        for(unsigned pass=0;pass<2u;pass++) for(unsigned i=0; i<48u;i++) {
            const wide_raster_site *s=pass?&g_wide_sites[i]:&original_sites[i];
            fprintf(f,"    {\"width\": %u, \"eip\": \"0x%05X\", \"hits\": %u, \"caller\": \"0x%08X\","
                " \"eax_first\": %u, \"ebx_first\": %u, \"ecx_first\": %u,"
                " \"edx_first\": %u, \"esi_first\": %u, \"edi_first\": %u,"
                " \"ebp_first\": %u, \"edi_min\": %u, \"edi_max\": %u,"
                " \"ecx_min\": %u, \"ecx_max\": %u, \"pitch_first\": %u,"
                " \"clip_first\": %u, \"rep_guest_destination_first\": \"0x%08X\", \"rep_guest_source_first\": \"0x%08X\", \"rep_bytes_first\": %u, \"rep_wscreen_overlap_bytes_first\": %u, \"in_surface\": %u, \"in_right_band\": %u, \"pre_instruction_branch_taken\": %s}%s\n",
                pass?672u:640u,g_wide_eips[i],s->hits,s->caller_first,s->eax_first,s->ebx_first,
                s->ecx_first,s->edx_first,s->esi_first,s->edi_first,s->ebp_first,
                s->edi_min,s->edi_max,s->ecx_min,s->ecx_max,s->pitch_first,
                s->clip_first,s->rep_guest_destination_first,s->rep_guest_source_first,
                s->rep_bytes_first,s->rep_wscreen_overlap_bytes_first,s->in_surface,s->in_right_band,
                (s->site==0x7C3DAu && (int32_t)s->eax_first < (int32_t)s->edi_first)?"true":"false",
                (pass==1u&&i==44u)?"":",");
        }
        fprintf(f,"  ]\n}\n"); fclose(f);
    }
    fprintf(stderr,"TRACE first_lateral_32_probe canonical=%d expanded=%d overlap=%u/307200 band_nonzero=%u colors=%u raster_hits=%u/%u\n",
        a,b,equal,nonzero,colors,original_sites[14].hits,g_wide_sites[14].hits);
    free(canonical.pixels);free(expanded.pixels);free(scratch);
    return a&&b;
}

static int run_hybrid_primitive_capture_probe(uint8_t *memory) {
    uint8_t *scratch=(uint8_t *)malloc(GUEST_LIMIT);
    if(!scratch) return 0;
    const uint64_t before=gw_hybrid_hash_guest(memory,GUEST_LIMIT);
    panorama_draw_result draw={0};
    gw_hybrid_primitive_capture_begin();
    memset(g_hybrid_pixel_write_mask,0,sizeof g_hybrid_pixel_write_mask);
    g_hybrid_pixel_write_count=0u;
    g_hybrid_wscreen=*(uint32_t *)(memory+0x00376A5Cu);
    g_hybrid_pixel_capture_enabled=1;
    g_hybrid_clear_surface=1;
    g_hybrid_use_game_draw=1;
    const int trace_was_enabled=gw_recomp_trace_enabled();
    gw_recomp_trace_set_enabled(1);
    gw_recomp_trace_watch_branch(0u);
    const uint32_t terrain_branches[]={0x662D4u,0x6631Au,0x6632Cu,0x66339u,
        0x663D7u,0x663E7u,0x663ECu,0x663F2u,0x66499u,0x664A0u,0x664A7u,
        0x664AEu,0x664E1u,0x664E6u,0x6652Cu,0x66541u,0x6654Eu,
        0x669ACu,0x669B3u,0x669BAu,0x669C1u,0x669F1u,0x669F6u,0x66A3Du};
    for(unsigned bi=0;bi<sizeof terrain_branches/sizeof terrain_branches[0];bi++)
        gw_recomp_trace_watch_branch(terrain_branches[bi]);
    recomp_set_guest_write_observer(gw_hybrid_capture_pixel_write,NULL);
    const int draw_ok=run_panorama_draw_pass(memory,scratch,0,0,&draw);
    recomp_set_guest_write_observer(NULL,NULL);
    gw_recomp_trace_watch_branch(0u);
    gw_recomp_trace_set_enabled(trace_was_enabled);
    g_hybrid_use_game_draw=0;
    g_hybrid_clear_surface=0;
    g_hybrid_pixel_capture_enabled=0;
    const int records_ok=gw_hybrid_primitive_capture_write(
        "evidence/hybrid_terrain_primitives_turn435.json");
    const int primitive_complete=records_ok&&g_hybrid_primitive_count>0u&&
        g_hybrid_primitive_total>0u;
    const int bmp_ok=draw_ok&&save_indexed_bmp24(
        "evidence/hybrid_terrain_reference640_turn435.bmp",draw.pixels,640u,480u,vga_dac);
    FILE *pixels=fopen("evidence/hybrid_terrain_pixel_commands_turn435.json","wb");
    int pixels_ok=0;
    if(pixels) {
        fprintf(pixels,"{\n  \"schema\":\"gwrecomp.hybrid-pixel-commands/v1\",\n"
            "  \"source\":\"original MapDisplay draw on private cleared WScreen\",\n"
            "  \"turn\":%u,\n  \"wscreen\":\"0x%08X\",\n  \"width\":640,\n  \"height\":480,\n"
            "  \"unique_written_pixels\":%u,\n  \"dac_rgb6\":[",
            *(uint32_t *)(memory+0x002F1472u),g_hybrid_wscreen,g_hybrid_pixel_write_count);
        for(unsigned i=0;i<768u;i++) fprintf(pixels,"%s%u",i?",":"",vga_dac[i]);
        fprintf(pixels,"],\n  \"commands\":[");
        unsigned emitted=0;
        for(uint32_t i=0;i<640u*480u;i++) if(g_hybrid_pixel_write_mask[i]) {
            fprintf(pixels,"%s[%u,%u,%u]",emitted++?",":"",i%640u,i/640u,draw.pixels?draw.pixels[i]:0u);
        }
        fprintf(pixels,"],\n  \"writers\":[");
        for(uint32_t wi=0;wi<g_hybrid_pixel_writer_count;wi++) {
            const gw_hybrid_pixel_writer *w=&g_hybrid_pixel_writers[wi];
            fprintf(pixels,"%s{\"eip\":\"0x%05X\",\"write_calls\":%u,\"bytes\":%u,\"guest_range\":[\"0x%08X\",\"0x%08X\"],\"xy_bounds\":[%u,%u,%u,%u],\"first_xy\":[%u,%u]}",
                wi?",":"",w->eip,w->calls,w->bytes,w->first_guest,w->last_guest,
                w->min_x,w->min_y,w->max_x,w->max_y,w->sample_x,w->sample_y);
        }
        fprintf(pixels,"],\n  \"writer_overflow_sites\":%u\n}\n",g_hybrid_pixel_writer_overflow);
        pixels_ok=fclose(pixels)==0;
    }
    const uint64_t after=gw_hybrid_hash_guest(memory,GUEST_LIMIT);
    uint32_t world_pixel_writes=0u;
    for(uint32_t p=0u;p<640u*480u;p++)
        if(g_hybrid_pixel_write_mask[p]&&(p%640u)>=128u) world_pixel_writes++;
    FILE *f=fopen("evidence/hybrid_terrain_capture_probe.json","wb");
    if(f) {
        fprintf(f,"{\n  \"schema\":\"gwrecomp.hybrid-terrain-capture-probe/v1\",\n"
            "  \"snapshot_turn\":%u,\n  \"canonical_draw\":{\"ok\":%s,\"width\":640,\"height\":480,\"pitch\":640,\"target\":\"0x%05X\",\"fault\":%s},\n"
            "  \"primitive_capture\":{\"ok\":%s,\"file_written\":%s,\"producer_0x65F20_entries\":%u,\"records\":%u,\"submissions\":%u,\"capture\":\"evidence/hybrid_terrain_primitives_turn435.json\"},\n"
            "  \"pixel_capture\":{\"ok\":%s,\"unique_written_pixels\":%u,\"writes_x_ge_128\":%u,\"capture\":\"evidence/hybrid_terrain_pixel_commands_turn435.json\"},\n"
            "  \"reference_bmp\":{\"ok\":%s,\"path\":\"evidence/hybrid_terrain_reference640_turn435.bmp\"},\n"
            "  \"snapshot_memory_hash_before\":\"0x%016llX\",\n  \"snapshot_memory_hash_after\":\"0x%016llX\",\n"
            "  \"snapshot_unchanged\":%s,\n  \"interpretation\":\"The original draw completed, but no 0xE19C0 primitive submissions were reached. The host pixel stream is sparse and has no writes in the world viewport x>=128; it is not a terrain capture.\"\n}\n",
            *(uint32_t *)(memory+0x002F1472u),draw_ok?"true":"false",draw.draw_target,
            draw.fault?"true":"false",primitive_complete?"true":"false",
            records_ok?"true":"false",g_hybrid_terrain_entry_count,g_hybrid_primitive_count,g_hybrid_primitive_total,
            pixels_ok?"true":"false",g_hybrid_pixel_write_count,world_pixel_writes,
            bmp_ok?"true":"false",
            (unsigned long long)before,(unsigned long long)after,before==after?"true":"false");
        fclose(f);
    }
    fprintf(stderr,"TRACE hybrid_terrain_capture probe_completed=%d primitive_complete=%d records=%u submissions=%u pixels=%u world_pixels=%u ref_bmp=%d snapshot_unchanged=%d\n",
        draw_ok&&records_ok&&bmp_ok&&pixels_ok,primitive_complete,g_hybrid_primitive_count,
        g_hybrid_primitive_total,g_hybrid_pixel_write_count,world_pixel_writes,bmp_ok,before==after);
    free(draw.pixels);
    free(scratch);
    return draw_ok&&records_ok&&bmp_ok&&pixels_ok&&g_hybrid_pixel_write_count>0u&&before==after;
}

